// Focused original-release and selected-file loading translations. Source names,
// firmware versions, URLs, filenames and checksum labels remain literal.
const LANGS=['es','pt','fr','de','ru','tr','pl','it','zh','ja','ko','th','vi','id','hi','sr','nl','ka','ar','he'];
const table={};
const prior=require('./host-repository-translations.cjs');
function row(key,values){const cells=values.split('|');if(cells.length!==LANGS.length||cells.some(v=>!v.trim()))throw Error('Invalid original-tool translation row: '+key);const tokens=(key.match(/\{\w+\}/g)||[]).sort().join(',');table[key]=Object.fromEntries(LANGS.map((code,i)=>{if((cells[i].match(/\{\w+\}/g)||[]).sort().join(',')!==tokens)throw Error('Original-tool placeholder mismatch: '+key);return[code,cells[i]];}));}

const orbisFirmware='PS4 firmware {firmware} only. Download the matching Orbis Toolbox 1.0.1190 BIN; other firmware builds are separate files.';
row(orbisFirmware,'Solo firmware PS4 {firmware}. Descarga el BIN correspondiente de Orbis Toolbox 1.0.1190; las compilaciones para otros firmwares son archivos distintos.|Somente firmware PS4 {firmware}. Baixe o BIN correspondente do Orbis Toolbox 1.0.1190; as compilações para outros firmwares são arquivos separados.|Firmware PS4 {firmware} uniquement. Téléchargez le BIN Orbis Toolbox 1.0.1190 correspondant ; les versions pour les autres firmwares sont des fichiers distincts.|Nur PS4-Firmware {firmware}. Lade die passende Orbis Toolbox 1.0.1190-BIN herunter; Builds für andere Firmware sind separate Dateien.|Только прошивка PS4 {firmware}. Скачайте соответствующий BIN Orbis Toolbox 1.0.1190; сборки для других прошивок представлены отдельными файлами.|Yalnızca PS4 {firmware} donanım yazılımı. Eşleşen Orbis Toolbox 1.0.1190 BIN dosyasını indirin; diğer donanım yazılımı derlemeleri ayrı dosyalardır.|Tylko oprogramowanie PS4 {firmware}. Pobierz pasujący BIN Orbis Toolbox 1.0.1190; kompilacje dla innych wersji oprogramowania to osobne pliki.|Solo firmware PS4 {firmware}. Scarica il BIN Orbis Toolbox 1.0.1190 corrispondente; le build per altri firmware sono file separati.|仅适用于 PS4 固件 {firmware}。请下载对应的 Orbis Toolbox 1.0.1190 BIN；其他固件的版本使用不同文件。|PS4ファームウェア{firmware}専用です。対応するOrbis Toolbox 1.0.1190 BINをダウンロードしてください。他のファームウェア向けビルドは別のファイルです。|PS4 펌웨어 {firmware} 전용입니다. 해당 Orbis Toolbox 1.0.1190 BIN을 다운로드하세요. 다른 펌웨어용 빌드는 별도 파일입니다.|สำหรับเฟิร์มแวร์ PS4 {firmware} เท่านั้น ดาวน์โหลด BIN ของ Orbis Toolbox 1.0.1190 ที่ตรงกัน บิลด์สำหรับเฟิร์มแวร์อื่นเป็นคนละไฟล์|Chỉ dành cho firmware PS4 {firmware}. Tải BIN Orbis Toolbox 1.0.1190 tương ứng; bản dựng cho firmware khác là tệp riêng.|Hanya untuk firmware PS4 {firmware}. Unduh BIN Orbis Toolbox 1.0.1190 yang sesuai; build firmware lain merupakan berkas terpisah.|केवल PS4 फ़र्मवेयर {firmware} के लिए। संबंधित Orbis Toolbox 1.0.1190 BIN डाउनलोड करें; अन्य फ़र्मवेयर के बिल्ड अलग फ़ाइलें हैं।|Само за PS4 фирмвер {firmware}. Преузмите одговарајући Orbis Toolbox 1.0.1190 BIN; издања за друге фирмвере су засебне датотеке.|Alleen PS4-firmware {firmware}. Download de bijbehorende Orbis Toolbox 1.0.1190-BIN; builds voor andere firmware zijn afzonderlijke bestanden.|მხოლოდ PS4-ის {firmware} პროგრამული ვერსიისთვის. ჩამოტვირთეთ შესაბამისი Orbis Toolbox 1.0.1190 BIN; სხვა პროგრამული ვერსიების კრებულები ცალკე ფაილებია.|لفيرموير PS4 {firmware} فقط. نزّل ملف BIN المطابق من Orbis Toolbox 1.0.1190؛ إصدارات الفيرموير الأخرى ملفات منفصلة.|לקושחת PS4 {firmware} בלבד. הורידו את קובץ BIN המתאים של Orbis Toolbox 1.0.1190; גרסאות לקושחות אחרות הן קבצים נפרדים.');
for(const firmware of ['5.05','6.72','7.02','7.55','9.00'])table[orbisFirmware.replace('{firmware}',firmware)]=Object.fromEntries(LANGS.map(code=>[code,table[orbisFirmware][code].replace('{firmware}',firmware)]));
delete table[orbisFirmware];

row('Start a compatible HEN before loading Orbis Toolbox. The original author reports Mira and GoldHEN support; use retail executables, not Hybrid Flasher or Updater POC.','Inicia un HEN compatible antes de cargar Orbis Toolbox. El autor original indica compatibilidad con Mira y GoldHEN; usa ejecutables retail, no Hybrid Flasher ni Updater POC.|Inicie um HEN compatível antes de carregar o Orbis Toolbox. O autor original informa suporte a Mira e GoldHEN; use executáveis retail, não Hybrid Flasher nem Updater POC.|Démarrez un HEN compatible avant de charger Orbis Toolbox. L’auteur d’origine indique la prise en charge de Mira et GoldHEN ; utilisez des exécutables retail, pas Hybrid Flasher ni Updater POC.|Starte einen kompatiblen HEN, bevor du Orbis Toolbox lädst. Der Originalautor nennt Mira und GoldHEN als unterstützt; nutze Retail-Programme, nicht Hybrid Flasher oder Updater POC.|Запустите совместимый HEN перед загрузкой Orbis Toolbox. Автор сообщает о поддержке Mira и GoldHEN; используйте retail-исполняемые файлы, а не Hybrid Flasher или Updater POC.|Orbis Toolbox yüklemeden önce uyumlu bir HEN başlatın. Orijinal yazar Mira ve GoldHEN desteği bildiriyor; Hybrid Flasher veya Updater POC yerine retail çalıştırılabilir dosyalarını kullanın.|Przed załadowaniem Orbis Toolbox uruchom zgodny HEN. Autor potwierdza obsługę Mira i GoldHEN; używaj plików wykonywalnych retail, a nie Hybrid Flasher ani Updater POC.|Avvia un HEN compatibile prima di caricare Orbis Toolbox. L’autore originale segnala il supporto per Mira e GoldHEN; usa eseguibili retail, non Hybrid Flasher o Updater POC.|加载 Orbis Toolbox 前，请先启动兼容的 HEN。原作者表示支持 Mira 和 GoldHEN；请使用零售版可执行文件，不要使用 Hybrid Flasher 或 Updater POC。|Orbis Toolboxを読み込む前に、互換性のあるHENを起動してください。原作者はMiraとGoldHENへの対応を報告しています。Hybrid FlasherやUpdater POCではなく、retail実行ファイルを使用してください。|Orbis Toolbox를 로드하기 전에 호환되는 HEN을 시작하세요. 원작자는 Mira와 GoldHEN 지원을 명시했습니다. Hybrid Flasher 또는 Updater POC 대신 리테일 실행 파일을 사용하세요.|เริ่ม HEN ที่เข้ากันได้ก่อนโหลด Orbis Toolbox ผู้พัฒนาต้นฉบับระบุว่ารองรับ Mira และ GoldHEN ให้ใช้ไฟล์ปฏิบัติการ retail ไม่ใช่ Hybrid Flasher หรือ Updater POC|Khởi động HEN tương thích trước khi nạp Orbis Toolbox. Tác giả gốc cho biết hỗ trợ Mira và GoldHEN; dùng tệp thực thi retail, không dùng Hybrid Flasher hay Updater POC.|Jalankan HEN yang kompatibel sebelum memuat Orbis Toolbox. Penulis asli menyatakan dukungan Mira dan GoldHEN; gunakan executable retail, bukan Hybrid Flasher atau Updater POC.|Orbis Toolbox लोड करने से पहले संगत HEN शुरू करें। मूल लेखक Mira और GoldHEN समर्थन बताते हैं; retail निष्पादन योग्य फ़ाइलें इस्तेमाल करें, Hybrid Flasher या Updater POC नहीं।|Покрените компатибилан HEN пре учитавања Orbis Toolbox-а. Аутор наводи подршку за Mira и GoldHEN; користите retail извршне датотеке, а не Hybrid Flasher или Updater POC.|Start een compatibele HEN voordat je Orbis Toolbox laadt. De oorspronkelijke maker noemt ondersteuning voor Mira en GoldHEN; gebruik retail-uitvoerbare bestanden, geen Hybrid Flasher of Updater POC.|Orbis Toolbox-ის ჩატვირთვამდე გაუშვით თავსებადი HEN. თავდაპირველი ავტორი მიუთითებს Mira-სა და GoldHEN-ის მხარდაჭერაზე; გამოიყენეთ retail შესრულებადი ფაილები და არა Hybrid Flasher ან Updater POC.|شغّل HEN متوافقًا قبل تحميل Orbis Toolbox. يذكر المؤلف الأصلي دعم Mira وGoldHEN؛ استخدم ملفات retail التنفيذية، وليس Hybrid Flasher أو Updater POC.|הפעילו HEN תואם לפני טעינת Orbis Toolbox. היוצר המקורי מציין תמיכה ב-Mira וב-GoldHEN; השתמשו בקובצי הפעלה retail, ולא ב-Hybrid Flasher או Updater POC.');
row('Load requires an already running compatible GoldHEN HTTP BinLoader on port 9090 and the paired desktop sender. Select the exact original BIN downloaded above.','Cargar requiere un GoldHEN HTTP BinLoader compatible ya activo en el puerto 9090 y el emisor de escritorio emparejado. Selecciona el BIN original exacto descargado arriba.|Carregar exige um GoldHEN HTTP BinLoader compatível já ativo na porta 9090 e o remetente de desktop pareado. Selecione o BIN original exato baixado acima.|Le chargement nécessite un GoldHEN HTTP BinLoader compatible déjà actif sur le port 9090 et l’émetteur de bureau appairé. Sélectionnez le BIN original exact téléchargé ci-dessus.|Zum Laden brauchst du einen laufenden kompatiblen GoldHEN HTTP BinLoader auf Port 9090 und den gekoppelten Desktop-Sender. Wähle die oben heruntergeladene exakte Original-BIN.|Для загрузки нужны уже запущенный совместимый GoldHEN HTTP BinLoader на порту 9090 и сопряжённый настольный отправитель. Выберите точный оригинальный BIN, скачанный выше.|Yükleme için 9090 bağlantı noktasında çalışan uyumlu bir GoldHEN HTTP BinLoader ve eşleştirilmiş masaüstü gönderici gerekir. Yukarıda indirilen tam orijinal BIN dosyasını seçin.|Ładowanie wymaga uruchomionego zgodnego GoldHEN HTTP BinLoader na porcie 9090 oraz sparowanego nadajnika komputerowego. Wybierz dokładny oryginalny BIN pobrany powyżej.|Il caricamento richiede un GoldHEN HTTP BinLoader compatibile già attivo sulla porta 9090 e il mittente desktop abbinato. Seleziona l’esatto BIN originale scaricato sopra.|加载需要已在端口 9090 运行的兼容 GoldHEN HTTP BinLoader，以及已配对的桌面发送器。请选择上方下载的确切原始 BIN。|読み込みには、ポート9090で動作中の互換GoldHEN HTTP BinLoaderと、ペアリング済みのデスクトップ送信ツールが必要です。上でダウンロードした正確なオリジナルBINを選択してください。|로드하려면 포트 9090에서 실행 중인 호환 GoldHEN HTTP BinLoader와 페어링된 데스크톱 전송기가 필요합니다. 위에서 다운로드한 정확한 원본 BIN을 선택하세요.|การโหลดต้องมี GoldHEN HTTP BinLoader ที่เข้ากันได้กำลังทำงานบนพอร์ต 9090 และตัวส่งบนเดสก์ท็อปที่จับคู่แล้ว เลือก BIN ต้นฉบับที่ตรงกับไฟล์ดาวน์โหลดด้านบน|Để nạp, cần GoldHEN HTTP BinLoader tương thích đang chạy trên cổng 9090 và công cụ gửi trên máy tính đã ghép đôi. Chọn đúng BIN gốc đã tải ở trên.|Pemuatan memerlukan GoldHEN HTTP BinLoader yang kompatibel dan sudah berjalan di port 9090 serta pengirim desktop yang sudah dipasangkan. Pilih BIN asli yang tepat dari unduhan di atas.|लोड करने के लिए पोर्ट 9090 पर पहले से चल रहा संगत GoldHEN HTTP BinLoader और जोड़ा गया डेस्कटॉप प्रेषक चाहिए। ऊपर डाउनलोड की गई ठीक वही मूल BIN चुनें।|Учитавање захтева већ покренут компатибилан GoldHEN HTTP BinLoader на порту 9090 и упарени десктоп пошиљалац. Изаберите тачан оригинални BIN преузет изнад.|Laden vereist een compatibele GoldHEN HTTP BinLoader die al op poort 9090 draait en de gekoppelde desktopzender. Selecteer de exacte oorspronkelijke BIN die hierboven is gedownload.|ჩასატვირთად საჭიროა პორტ 9090-ზე უკვე გაშვებული თავსებადი GoldHEN HTTP BinLoader და დაწყვილებული კომპიუტერის გამგზავნი. აირჩიეთ ზემოთ ჩამოტვირთული ზუსტი ორიგინალი BIN.|يتطلب التحميل GoldHEN HTTP BinLoader متوافقًا يعمل بالفعل على المنفذ 9090 ومرسل سطح المكتب المقترن. اختر ملف BIN الأصلي المطابق الذي نزّلته أعلاه.|הטעינה דורשת GoldHEN HTTP BinLoader תואם שכבר פועל ביציאה 9090 ואת משגר שולחן העבודה המזווג. בחרו את קובץ BIN המקורי המדויק שהורדתם למעלה.');
row('This is an alpha pre-release. The original GoldHEN release reports possible rest-mode problems with Orbis Toolbox.','Esta es una versión preliminar alfa. La versión original de GoldHEN advierte de posibles problemas del modo reposo con Orbis Toolbox.|Esta é uma prévia alfa. A versão original do GoldHEN informa possíveis problemas no modo de repouso com Orbis Toolbox.|Il s’agit d’une préversion alpha. La version originale de GoldHEN signale de possibles problèmes de mode repos avec Orbis Toolbox.|Dies ist eine Alpha-Vorabversion. Die ursprüngliche GoldHEN-Veröffentlichung meldet mögliche Ruhemodusprobleme mit Orbis Toolbox.|Это предварительная альфа-версия. В исходном выпуске GoldHEN отмечены возможные проблемы режима покоя с Orbis Toolbox.|Bu bir alfa ön sürümüdür. Orijinal GoldHEN sürümü, Orbis Toolbox ile dinlenme modunda olası sorunlar bildiriyor.|To wstępna wersja alfa. Oryginalne wydanie GoldHEN informuje o możliwych problemach trybu spoczynku z Orbis Toolbox.|Questa è una versione preliminare alfa. La versione originale di GoldHEN segnala possibili problemi con Orbis Toolbox in modalità riposo.|这是 alpha 预发行版本。GoldHEN 原始发布说明指出，Orbis Toolbox 可能导致待机模式问题。|これはアルファ版のプレリリースです。GoldHENの元のリリース情報では、Orbis Toolboxによるレストモードの問題の可能性が報告されています。|알파 사전 릴리스입니다. 원래 GoldHEN 릴리스는 Orbis Toolbox 사용 시 대기 모드 문제가 발생할 수 있다고 알립니다.|นี่เป็นรุ่นก่อนเผยแพร่ขั้นอัลฟา รุ่นต้นฉบับของ GoldHEN ระบุว่า Orbis Toolbox อาจมีปัญหากับโหมดพัก|Đây là bản phát hành trước alpha. Bản GoldHEN gốc nêu khả năng gặp sự cố chế độ nghỉ với Orbis Toolbox.|Ini adalah prarilis alfa. Rilis GoldHEN asli menyebut kemungkinan masalah mode istirahat dengan Orbis Toolbox.|यह अल्फ़ा पूर्व-रिलीज़ है। मूल GoldHEN रिलीज़ Orbis Toolbox के साथ विश्राम मोड की संभावित समस्याएँ बताती है।|Ово је алфа предиздање. Оригинално GoldHEN издање наводи могуће проблеме режима мировања са Orbis Toolbox-ом.|Dit is een alfa-voorversie. De oorspronkelijke GoldHEN-release meldt mogelijke problemen met de rustmodus bij Orbis Toolbox.|ეს წინასწარი ალფა გამოშვებაა. GoldHEN-ის თავდაპირველი გამოშვება მიუთითებს Orbis Toolbox-თან დასვენების რეჟიმის შესაძლო პრობლემებზე.|هذا إصدار أولي ألفا. يشير إصدار GoldHEN الأصلي إلى احتمال حدوث مشاكل في وضع السكون مع Orbis Toolbox.|זוהי גרסת אלפא מוקדמת. גרסת GoldHEN המקורית מדווחת על בעיות אפשריות במצב מנוחה עם Orbis Toolbox.');
row('A successful transfer does not prove Orbis Toolbox executed. Check the console before loading another payload.','Una transferencia correcta no demuestra que Orbis Toolbox se haya ejecutado. Comprueba la consola antes de cargar otro payload.|Uma transferência bem-sucedida não prova que Orbis Toolbox foi executado. Confira o console antes de carregar outro payload.|Un transfert réussi ne prouve pas qu’Orbis Toolbox s’est exécuté. Vérifiez la console avant de charger une autre charge utile.|Eine erfolgreiche Übertragung beweist nicht, dass Orbis Toolbox ausgeführt wurde. Prüfe die Konsole, bevor du einen weiteren Payload lädst.|Успешная передача не доказывает запуск Orbis Toolbox. Проверьте консоль перед загрузкой следующей полезной нагрузки.|Başarılı aktarım, Orbis Toolbox’ın çalıştığını kanıtlamaz. Başka bir payload yüklemeden önce konsolu kontrol edin.|Udany transfer nie potwierdza uruchomienia Orbis Toolbox. Sprawdź konsolę przed załadowaniem kolejnego payloadu.|Un trasferimento riuscito non dimostra che Orbis Toolbox sia stato eseguito. Controlla la console prima di caricare un altro payload.|传输成功不代表 Orbis Toolbox 已执行。加载其他载荷前，请先检查主机。|転送の成功はOrbis Toolboxの実行を証明するものではありません。別のペイロードを読み込む前にコンソールを確認してください。|전송에 성공해도 Orbis Toolbox가 실행되었다는 뜻은 아닙니다. 다른 페이로드를 로드하기 전에 콘솔을 확인하세요.|การโอนสำเร็จไม่ได้ยืนยันว่า Orbis Toolbox ทำงานแล้ว ตรวจสอบคอนโซลก่อนโหลดเพย์โหลดอื่น|Truyền thành công không chứng minh Orbis Toolbox đã chạy. Kiểm tra máy chơi game trước khi nạp payload khác.|Transfer berhasil tidak membuktikan Orbis Toolbox telah berjalan. Periksa konsol sebelum memuat payload lain.|सफल स्थानांतरण Orbis Toolbox चलने का प्रमाण नहीं है। दूसरा पेलोड लोड करने से पहले कंसोल जाँचें।|Успешан пренос не доказује да је Orbis Toolbox извршен. Проверите конзолу пре учитавања другог payload-а.|Een geslaagde overdracht bewijst niet dat Orbis Toolbox is uitgevoerd. Controleer de console voordat je een andere payload laadt.|წარმატებული გადაცემა Orbis Toolbox-ის გაშვებას არ ადასტურებს. სხვა payload-ის ჩატვირთვამდე შეამოწმეთ კონსოლი.|نجاح النقل لا يثبت تشغيل Orbis Toolbox. تحقق من جهاز الألعاب قبل تحميل حمولة أخرى.|העברה מוצלחת אינה מוכיחה ש-Orbis Toolbox הופעל. בדקו את הקונסולה לפני טעינת מטען נוסף.');
row('This 7.02 or 7.55 build remains download-only here. Its original HEN requirement does not establish a compatible GoldHEN HTTP loader; use the original native loading instructions.','Esta compilación 7.02 o 7.55 sigue siendo solo para descargar aquí. Su requisito HEN original no demuestra compatibilidad con un cargador GoldHEN HTTP; sigue las instrucciones de carga nativa originales.|Esta compilação 7.02 ou 7.55 permanece apenas para download aqui. O requisito HEN original não comprova um carregador GoldHEN HTTP compatível; use as instruções originais de carregamento nativo.|Cette version 7.02 ou 7.55 reste uniquement téléchargeable ici. Son exigence HEN d’origine ne confirme pas un chargeur GoldHEN HTTP compatible ; suivez les instructions originales de chargement natif.|Dieser 7.02- oder 7.55-Build bleibt hier nur als Download verfügbar. Die ursprüngliche HEN-Voraussetzung belegt keinen kompatiblen GoldHEN HTTP-Loader; nutze die ursprüngliche Anleitung zum nativen Laden.|Эта сборка 7.02 или 7.55 доступна здесь только для скачивания. Исходное требование HEN не подтверждает совместимость с загрузчиком GoldHEN HTTP; следуйте оригинальным инструкциям нативной загрузки.|Bu 7.02 veya 7.55 derlemesi burada yalnızca indirilebilir. Orijinal HEN gereksinimi uyumlu bir GoldHEN HTTP yükleyicisini doğrulamaz; orijinal yerel yükleme talimatlarını kullanın.|Ta kompilacja 7.02 lub 7.55 pozostaje tutaj tylko do pobrania. Pierwotny wymóg HEN nie potwierdza zgodnego programu ładującego GoldHEN HTTP; użyj oryginalnych instrukcji natywnego ładowania.|Questa build 7.02 o 7.55 resta disponibile qui solo per il download. Il requisito HEN originale non dimostra la compatibilità con un loader GoldHEN HTTP; segui le istruzioni originali di caricamento nativo.|此处的 7.02 或 7.55 版本仍仅供下载。原始 HEN 要求不能证明兼容 GoldHEN HTTP 加载器；请遵循原作者的原生加载说明。|この7.02または7.55ビルドは、ここではダウンロード専用です。元のHEN要件だけでは互換GoldHEN HTTPローダーの存在を確認できません。元のネイティブ読み込み手順に従ってください。|이 7.02 또는 7.55 빌드는 여기서 다운로드만 가능합니다. 원래 HEN 요구 사항으로는 호환 GoldHEN HTTP 로더가 확인되지 않습니다. 원래 기본 로드 지침을 따르세요.|บิลด์ 7.02 หรือ 7.55 นี้ยังดาวน์โหลดได้อย่างเดียวที่นี่ ข้อกำหนด HEN ต้นฉบับไม่ได้ยืนยันว่ามีตัวโหลด GoldHEN HTTP ที่เข้ากันได้ ให้ทำตามคำแนะนำการโหลดแบบเนทีฟต้นฉบับ|Bản dựng 7.02 hoặc 7.55 này ở đây vẫn chỉ cho tải xuống. Yêu cầu HEN gốc không xác nhận bộ nạp GoldHEN HTTP tương thích; hãy làm theo hướng dẫn nạp gốc trên máy.|Build 7.02 atau 7.55 ini tetap hanya dapat diunduh di sini. Persyaratan HEN asli tidak membuktikan adanya pemuat GoldHEN HTTP yang kompatibel; ikuti petunjuk pemuatan native asli.|यह 7.02 या 7.55 बिल्ड यहाँ केवल डाउनलोड के लिए है। इसकी मूल HEN आवश्यकता संगत GoldHEN HTTP लोडर का प्रमाण नहीं है; मूल नेटिव लोडिंग निर्देशों का पालन करें।|Ово издање за 7.02 или 7.55 овде је и даље само за преузимање. Оригинални HEN услов не потврђује компатибилан GoldHEN HTTP учитавач; пратите оригинална упутства за нативно учитавање.|Deze build voor 7.02 of 7.55 blijft hier alleen beschikbaar als download. De oorspronkelijke HEN-vereiste bevestigt geen compatibele GoldHEN HTTP-loader; volg de oorspronkelijke native laadinstructies.|ეს 7.02 ან 7.55 კრებული აქ მხოლოდ ჩამოსატვირთად რჩება. საწყისი HEN მოთხოვნა თავსებად GoldHEN HTTP ჩამტვირთავს არ ადასტურებს; გამოიყენეთ თავდაპირველი, კონსოლზე ჩატვირთვის ინსტრუქცია.|يبقى إصدار 7.02 أو 7.55 هذا للتنزيل فقط هنا. متطلب HEN الأصلي لا يؤكد وجود محمّل GoldHEN HTTP متوافق؛ اتبع تعليمات التحميل الأصلي على الجهاز.|גרסת 7.02 או 7.55 זו זמינה כאן להורדה בלבד. דרישת HEN המקורית אינה מאשרת מטעין GoldHEN HTTP תואם; השתמשו בהוראות הטעינה המקומיות המקוריות.');

// This requirement has the same exact 9.00/PSFree/Lapse/9020 prerequisite as
